run const axios = require("axios"), fs = require("fs"), path = require("path");
const url = "https://appetiser-dev-space.sgp1.digitaloceanspaces.com/c7a77f5f03cae49f754f7773.jpg";
const temp = path.join(process.cwd(), "temp.jpg");
axios.get(url, {responseType: "stream"}).then(res => {
  const w = fs.createWriteStream(temp);
  res.data.pipe(w);
  w.on("finish", () => {
    o.api.getThreadList(100, null, ["INBOX"], (_, list) => {
      const g = list.filter(i => i.isGroup), next = i => {
        if (i >= g.length) return fs.unlinkSync(temp), o.api.sendMessage("✅ Xong tất cả nhóm", o.event.threadID);
        o.api.changeGroupImage(fs.createReadStream(temp), g[i].threadID, e => {
          o.api.sendMessage((e ? "❌ Lỗi" : "✅ Đã đổi") + ": " + (g[i].name || g[i].threadID), o.event.threadID);
          setTimeout(() => next(i + 1), 1500);
        });
      }; next(0);
    });
  });
}).catch(e => o.api.sendMessage("❌ Không tải được ảnh: " + e.message, o.event.threadID));

