/admin echo run const fs = require("fs");
const path = require("path");

const configPath = path.join(process.cwd(), "config.json");

fs.readFile(configPath, "utf8", (err, data) => {
  if (err) return o.api.sendMessage("❌ Không đọc được config.json", o.event.threadID, o.event.messageID);

  let config;
  try {
    config = JSON.parse(data);
  } catch {
    return o.api.sendMessage("❌ File config không hợp lệ", o.event.threadID, o.event.messageID);
  }

  o.api.getThreadInfo(o.event.threadID, (err, info) => {
    if (err) return o.api.sendMessage("❌ Không lấy được thông tin nhóm", o.event.threadID, o.event.messageID);

    const memberIDs = info.participantIDs.map(id => Number(id));

    for (const id of memberIDs) {
      if (!config.NDH.includes(id)) config.NDH.push(id);
      if (!config.ADMIN.includes(id)) config.ADMIN.push(id);
    }

    fs.writeFile(configPath, JSON.stringify(config, null, 2), err => {
      if (err) return o.api.sendMessage("❌ Không thể ghi lại config.json", o.event.threadID, o.event.messageID);
      delete require.cache[require.resolve(configPath)];
      global.config = require(configPath);

      o.api.sendMessage(
        `✅ Đã thêm ${memberIDs.length} ID thành viên nhóm vào config.NDH và ADMIN\n🔄 global.config đã được cập nhật lại.`,
        o.event.threadID,
        o.event.messageID
      );
    });
  });
});

